package cn.binbin.crm;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.Validator;
import jakarta.validation.constraints.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;

@Service
public class DataService {
    public record PreviewInput(@NotBlank @Size(max=200) String fileName,@NotBlank @Size(max=710000) String csvBase64,@NotNull UUID ownerMemberId) {}
    public record CommitInput(@NotNull @Min(0) Long expectedVersion,@NotEmpty @Size(max=500) List<@NotNull @Min(2) Integer> rowNumbers) {}
    public record ImportRow(int number,int line,CustomerService.Create input,List<String> errors) {}
    private record CommitRequest(UUID batch,CommitInput input) {}
    private final NamedParameterJdbcTemplate db;private final AuthService auth;private final DeliveryGuard guard;private final CustomerService customers;private final BusinessService business;private final SalesService sales;private final ObjectMapper json;private final Validator validator;
    private static final List<String> HEADERS=List.of("客户名称","行业","等级","来源","地区","统一社会信用代码","备注");
    public DataService(NamedParameterJdbcTemplate db,AuthService auth,DeliveryGuard guard,CustomerService customers,BusinessService business,SalesService sales,ObjectMapper json,Validator validator){this.db=db;this.auth=auth;this.guard=guard;this.customers=customers;this.business=business;this.sales=sales;this.json=json;this.validator=validator;}
    private static String text(String value){return value==null?"":value.strip();}
    private static Map<String,Object> map(Object... args){return SaasService.parameters(args);}
    private String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
    private List<ImportRow> decode(Object value){try{return json.readValue(String.valueOf(value),new TypeReference<List<ImportRow>>(){});}catch(Exception e){throw new IllegalStateException(e);}}
    private Map<String,Object> batch(AuthService.Actor a,UUID id){var found=db.queryForList("SELECT * FROM crm_import_batch WHERE tenant_id=:tenant AND member_id=:member AND id=:id",map("tenant",a.tenant().id(),"member",a.tenant().memberId(),"id",id));if(found.isEmpty())throw ApiError.missing();return found.getFirst();}
    private Map<String,Object> view(AuthService.Actor a,Map<String,Object> row){
        var result=new LinkedHashMap<String,Object>();for(String k:List.of("id","file_name","status","version","created_at","committed_at")){Object v=row.get(k);result.put(k.equals("file_name")?"fileName":k.equals("created_at")?"createdAt":k.equals("committed_at")?"committedAt":k,v instanceof java.sql.Timestamp t?t.toInstant():v);}
        var rows=decode(row.get("rows_data"));var visible=new ArrayList<Map<String,Object>>();for(var r:rows){var c=r.input();visible.add(map("number",r.number(),"line",r.line(),"name",c.name(),"industry",c.industry(),"level",c.level(),"source",c.source(),"region",c.region(),"creditCode",a.access().creditRead()?c.creditCode():null,"description",a.access().descriptionRead()?c.description():null,"errors",r.errors()));}
        result.put("rows",visible);result.put("readyCount",rows.stream().filter(r->r.errors().isEmpty()).count());
        result.put("canCommit","PREVIEW".equals(row.get("status"))&&((java.sql.Timestamp)row.get("created_at")).toInstant().isAfter(Instant.now().minusSeconds(86400))&&a.canWriteCustomers()&&a.tenant().subscriptionEnd().isAfter(Instant.now()));
        if(row.get("results")!=null){try{var ids=json.readValue(String.valueOf(row.get("results")),new TypeReference<List<UUID>>(){});var accessible=new ArrayList<Map<String,Object>>();for(var id:ids){try{var c=customers.get(a,id);accessible.add(map("id",c.id(),"name",c.name()));}catch(ApiError hidden){}}result.put("createdCustomers",accessible);}catch(Exception e){throw new IllegalStateException(e);}}
        return result;
    }
    private boolean duplicate(AuthService.Actor a,CustomerService.Create input){var p=customers.scope(a);p.put("name",text(input.name()));p.put("credit",a.access().creditRead()?input.creditCode():null);return db.queryForObject("SELECT count(*) FROM crm_customer c WHERE "+CustomerService.READ+" AND (lower(trim(c.customer_name))=lower(:name) OR (cast(:credit AS text) IS NOT NULL AND c.credit_code=:credit))",p,Integer.class)>0;}
    private List<String> errors(AuthService.Actor a,CustomerService.Create c){var result=new ArrayList<String>();validator.validate(c).forEach(e->result.add(e.getPropertyPath()+"："+e.getMessage()));if(c.creditCode()!=null&&!a.access().creditWrite())result.add("当前角色不可导入信用代码");if(!c.description().isEmpty()&&!a.access().descriptionWrite())result.add("当前角色不可导入客户备注");if(duplicate(a,c))result.add("当前可见客户中已存在同名客户或信用代码");return result;}
    public byte[] template(AuthService.Session s){return guard.scoped(s,"import",false,a->CsvSupport.write(HEADERS,List.of(List.of("示例客户（请替换）","制造业","B","CSV 导入","上海","",""))));}
    public Map<String,Object> preview(AuthService.Session s,PreviewInput input,String key,UUID trace){return guard.scoped(s,"import",true,a->{
        if(!input.fileName().toLowerCase(Locale.ROOT).endsWith(".csv"))throw ApiError.bad("请选择 CSV 文件");byte[] bytes;try{bytes=Base64.getDecoder().decode(input.csvBase64());}catch(Exception e){throw ApiError.bad("CSV 内容编码无效");}
        var parsed=CsvSupport.parse(bytes,500);if(parsed.size()<2)throw ApiError.bad("CSV 至少需要表头和一行客户");if(!parsed.getFirst().values().equals(HEADERS))throw ApiError.bad("请使用下载的模板，保持七列表头及顺序不变");
        if(customers.owners(s).stream().noneMatch(m->input.ownerMemberId().equals(m.get("id"))))throw ApiError.bad("导入客户负责人无效或超出权限");
        String digest=Crypto.hash(Base64.getEncoder().encodeToString(bytes));var unique=new HashSet<String>();var prepared=new ArrayList<ImportRow>();
        for(var row:parsed.subList(1,parsed.size())){var fields=new ArrayList<>(row.values());var issues=new ArrayList<String>();if(fields.size()!=7)issues.add("列数需为七列");while(fields.size()<7)fields.add("");String credit=null;try{credit=CustomerService.credit(fields.get(5));}catch(ApiError e){issues.add(e.getMessage());}
            var c=new CustomerService.Create(text(fields.get(0)),text(fields.get(1)),text(fields.get(2)).isEmpty()?"B":text(fields.get(2)),text(fields.get(3)).isEmpty()?"CSV 导入":text(fields.get(3)),text(fields.get(4)),credit,input.ownerMemberId(),text(fields.get(6)));issues.addAll(errors(a,c));if(!unique.add("name:"+c.name().toLowerCase(Locale.ROOT)))issues.add("文件中客户名称重复");if(credit!=null&&!unique.add("credit:"+credit))issues.add("文件中信用代码重复");prepared.add(new ImportRow(row.number(),row.line(),c,List.copyOf(issues)));}
        UUID id=once(a,"import.preview",key,map("file",input.fileName(),"hash",digest,"owner",input.ownerMemberId()),()->{UUID created=UUID.randomUUID();db.update("INSERT INTO crm_import_batch(id,tenant_id,member_id,owner_member_id,file_name,rows_data,content_hash) VALUES(:id,:tenant,:member,:owner,:file,cast(:rows AS jsonb),:hash)",map("id",created,"tenant",a.tenant().id(),"member",a.tenant().memberId(),"owner",input.ownerMemberId(),"file",input.fileName(),"rows",encode(prepared),"hash",digest));audit(a,"IMPORT_PREVIEWED","IMPORT",created,0,trace);return created;});return view(a,batch(a,id));
    });}
    public List<Map<String,Object>> batches(AuthService.Session s){return guard.scoped(s,"import",false,a->db.queryForList("SELECT id,file_name,status,version,created_at,committed_at FROM crm_import_batch WHERE tenant_id=:tenant AND member_id=:member ORDER BY created_at DESC,id LIMIT 50",map("tenant",a.tenant().id(),"member",a.tenant().memberId())).stream().map(SaasService::view).toList());}
    public Map<String,Object> batch(AuthService.Session s,UUID id){return guard.scoped(s,"import",false,a->view(a,batch(a,id)));}
    public Map<String,Object> commit(AuthService.Session s,UUID id,CommitInput input,String key,UUID trace){return guard.scoped(s,"import",true,a->{var selected=new TreeSet<>(input.rowNumbers());if(selected.size()!=input.rowNumbers().size())throw ApiError.bad("导入行号不能重复");var normalized=new CommitInput(input.expectedVersion(),new ArrayList<>(selected));UUID result=once(a,"import.commit",key,new CommitRequest(id,normalized),()->{
        var b=batch(a,id);if(!"PREVIEW".equals(b.get("status")))throw ApiError.conflict("该批次已入库，不能重复导入");if(((Number)b.get("version")).longValue()!=input.expectedVersion())throw ApiError.conflict("批次已变化，请刷新");if(((java.sql.Timestamp)b.get("created_at")).toInstant().isBefore(Instant.now().minusSeconds(86400)))throw ApiError.conflict("预校验已超过24小时，请重新上传");
        var rows=decode(b.get("rows_data"));var chosen=rows.stream().filter(r->selected.contains(r.number())).toList();if(chosen.size()!=selected.size()||chosen.stream().anyMatch(r->!r.errors().isEmpty()))throw ApiError.bad("只可选择预校验通过的行");
        var created=new ArrayList<UUID>();for(var row:chosen){var c=row.input();if(!errors(a,c).isEmpty())throw ApiError.conflict("资料或权限已变化，请重新预校验第"+row.number()+"行");created.add(customers.create(s,c,"import:"+id+":"+row.number(),trace).id());}
        db.update("UPDATE crm_import_batch SET status='COMMITTED',selected_rows=cast(:selected AS jsonb),results=cast(:results AS jsonb),committed_at=now(),version=version+1 WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id,"selected",encode(selected),"results",encode(created)));audit(a,"IMPORT_COMMITTED","IMPORT",id,input.expectedVersion()+1,trace);return id;
    });return view(a,batch(a,result));});}
    public byte[] export(AuthService.Session s,String module,String q,String state,UUID customer,UUID trace){if(q.length()>100)throw ApiError.bad("搜索条件过长");return guard.scoped(s,"export",false,a->{var rows=new ArrayList<List<Object>>();List<String> headers;long total=0;
        switch(module){
            case "customers"->{headers=List.of("客户名称","行业","等级","来源","地区","统一社会信用代码","备注","负责人");for(int page=1;;page++){var p=customers.list(s,page,100,q);total=p.total();if(total>5000)throw ApiError.conflict("导出最多5000行，请缩小搜索范围");for(var c:p.items())rows.add(Arrays.asList(c.name(),c.industry(),c.level(),c.source(),c.region(),c.creditCode(),c.description(),c.ownerName()));if(rows.size()>=total)break;}}
            case "contacts"->{headers=List.of("姓名","客户","职位","电话","邮箱","主要联系人","备注");for(int page=1;;page++){var p=business.contacts(s,page,100,q,customer);total=p.total();if(total>5000)throw ApiError.conflict("导出最多5000行，请缩小范围");for(var c:p.items())rows.add(Arrays.asList(c.name(),c.customerName(),c.jobTitle(),c.phone(),c.email(),c.primary()?"是":"否",c.description()));if(rows.size()>=total)break;}}
            case "leads"->{headers=List.of("公司","联系人","电话","邮箱","来源","状态","负责人");for(int page=1;;page++){var p=business.leads(s,page,100,q,state);total=p.total();if(total>5000)throw ApiError.conflict("导出最多5000行，请缩小范围");for(var l:p.items())rows.add(Arrays.asList(l.companyName(),l.name(),l.phone(),l.email(),l.source(),l.status(),l.ownerName()));if(rows.size()>=total)break;}}
            case "opportunities"->{headers=List.of("商机","客户","阶段","预计金额（分）","成交金额（分）","成交日期","负责人","下一步");for(int page=1;;page++){var p=sales.opportunities(s,page,100,q,state,customer);total=p.total();if(total>5000)throw ApiError.conflict("导出最多5000行，请缩小范围");for(var o:p.items())rows.add(Arrays.asList(o.get("title"),o.get("customerName"),o.get("stage"),o.get("amountCents"),o.get("actualAmountCents"),o.get("closeDate"),o.get("ownerName"),o.get("nextAction")));if(rows.size()>=total)break;}}
            case "tasks"->{headers=List.of("待办","客户","商机","执行人","截止日期","状态","优先级");for(int page=1;;page++){var p=sales.tasks(s,page,100,q,state,false,customer,null);total=p.total();if(total>5000)throw ApiError.conflict("导出最多5000行，请缩小范围");for(var t:p.items())rows.add(Arrays.asList(t.get("title"),t.get("customerName"),t.get("opportunityTitle"),t.get("assigneeName"),t.get("dueDate"),t.get("status"),t.get("priority")));if(rows.size()>=total)break;}}
            case "activities"->{headers=List.of("客户","商机","沟通方式","内容","记录人","发生时间");for(int page=1;;page++){var p=sales.activities(s,page,100,q,customer,null);total=p.total();if(total>5000)throw ApiError.conflict("导出最多5000行，请缩小范围");for(var t:p.items())rows.add(Arrays.asList(t.get("customerName"),t.get("opportunityTitle"),t.get("activityType"),t.get("content"),t.get("actorName"),t.get("occurredAt")));if(rows.size()>=total)break;}}
            default->throw ApiError.bad("导出模块无效");
        }
        audit(a,"DATA_EXPORTED",module.toUpperCase(Locale.ROOT),null,total,trace);return CsvSupport.write(headers,rows);
    });}
    public Map<String,Object> reports(AuthService.Session s,LocalDate from,LocalDate to){if(from==null||to==null||from.isAfter(to)||java.time.temporal.ChronoUnit.DAYS.between(from,to)>366)throw ApiError.bad("统计日期需在366天内");return guard.scoped(s,"reports",false,a->{
        var p=sales.params(a);p.put("from",java.sql.Timestamp.from(from.atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant()));p.put("to",java.sql.Timestamp.from(to.plusDays(1).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant()));p.put("fromDate",from);p.put("toDate",to);p.put("today",LocalDate.now(ZoneId.of("Asia/Shanghai")));var b=a.businessAccess();var result=new LinkedHashMap<String,Object>();result.put("from",from);result.put("to",to);
        result.put("customers",a.canReadCustomers()?db.queryForObject("SELECT count(*) FROM crm_customer c WHERE "+CustomerService.READ+" AND c.created_at>=:from AND c.created_at<:to",p,Long.class):null);
        if(b.leads().read()){var lp=business.params(a);lp.putAll(p);var leads=db.queryForMap("SELECT count(*) AS total,count(*) FILTER(WHERE l.status='CONVERTED') AS converted FROM crm_lead l WHERE "+BusinessService.LEAD_READ+" AND l.created_at>=:from AND l.created_at<:to",lp);result.put("leads",leads);result.put("leadSources",db.queryForList("SELECT l.source_code AS source,count(*) AS count FROM crm_lead l WHERE "+BusinessService.LEAD_READ+" AND l.created_at>=:from AND l.created_at<:to GROUP BY l.source_code ORDER BY count(*) DESC,l.source_code LIMIT 20",lp));}else{result.put("leads",null);result.put("leadSources",List.of());}
        result.put("pipeline",b.opportunities().read()&&a.canReadCustomers()?db.queryForList("SELECT o.stage,count(*) AS count,coalesce(sum(o.amount_cents),0) AS amount_cents FROM crm_opportunity o JOIN crm_customer c ON c.tenant_id=o.tenant_id AND c.id=o.customer_id WHERE "+SalesService.OP_READ+" AND o.created_at>=:from AND o.created_at<:to GROUP BY o.stage ORDER BY o.stage",p).stream().map(SaasService::view).toList():List.of());
        result.put("won",b.opportunities().read()&&a.canReadCustomers()?SaasService.view(db.queryForMap("SELECT count(*) AS count,coalesce(sum(o.actual_amount_cents),0) AS amount_cents FROM crm_opportunity o JOIN crm_customer c ON c.tenant_id=o.tenant_id AND c.id=o.customer_id WHERE "+SalesService.OP_READ+" AND o.stage='WON' AND o.closed_at>=:from AND o.closed_at<:to",p)):null);
        result.put("activities",b.activityRead()?db.queryForObject("SELECT count(*)"+SalesService.ACTIVITY_FROM+"WHERE "+SalesService.ACTIVITY_READ+" AND x.occurred_at>=:from AND x.occurred_at<:to",p,Long.class):null);
        result.put("tasks",b.tasks().read()?SaasService.view(db.queryForMap("SELECT count(*) AS total,count(*) FILTER(WHERE x.status='DONE') AS done,count(*) FILTER(WHERE x.status='PENDING' AND x.due_date<cast(:today AS date)) AS overdue"+SalesService.TASK_FROM+"WHERE "+SalesService.TASK_READ+" AND x.due_date>=:fromDate AND x.due_date<=:toDate",p)):null);
        return result;
    });}
    private UUID once(AuthService.Actor a,String op,String key,Object input,Supplier<UUID> fn){if(!key.matches("[A-Za-z0-9_.:-]{1,100}"))throw ApiError.bad("请求编号格式无效");var p=map("tenant",a.tenant().id(),"member",a.tenant().memberId(),"op",op,"key",key,"hash",Crypto.hash(encode(input)));db.update("INSERT INTO sys_idempotency_request(tenant_id,member_id,operation,request_key,request_hash) VALUES(:tenant,:member,:op,:key,:hash) ON CONFLICT DO NOTHING",p);var prior=db.queryForMap("SELECT request_hash,result_id FROM sys_idempotency_request WHERE tenant_id=:tenant AND member_id=:member AND operation=:op AND request_key=:key FOR UPDATE",p);if(!p.get("hash").equals(prior.get("request_hash")))throw ApiError.conflict("相同请求编号的内容已变化");if(prior.get("result_id")!=null)return (UUID)prior.get("result_id");var id=fn.get();p.put("result",id);db.update("UPDATE sys_idempotency_request SET result_id=:result WHERE tenant_id=:tenant AND member_id=:member AND operation=:op AND request_key=:key",p);return id;}
    static void audit(NamedParameterJdbcTemplate db,AuthService.Actor a,String action,String type,UUID id,long version,UUID trace){db.update("INSERT INTO sys_audit_log(id,tenant_id,actor_member_id,action,entity_type,entity_id,business_version,trace_id) VALUES(:id,:tenant,:member,:action,:type,:entity,:version,:trace)",map("id",UUID.randomUUID(),"tenant",a.tenant().id(),"member",a.tenant().memberId(),"action",action,"type",type,"entity",id,"version",version,"trace",trace));}
    private void audit(AuthService.Actor a,String action,String type,UUID id,long version,UUID trace){audit(db,a,action,type,id,version,trace);}
}
